{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_vs_category_str AS WITH capsule_mapping AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU_GROUP, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), focus_capsules AS ( SELECT DISTINCT SKU_GROUP, CAPSULE FROM capsule_mapping WHERE LOWER(TRIM(CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\' ) ), category_base AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, L1_CATEGORY, CATEGORY, COALESCE(OVERALL_L30D_QTY, 0) AS L30D_QTY, COALESCE(OVERALL_INWARD_QTY, 0) AS INWARD_QTY, COALESCE(INV_CURRENT, 0) AS CURRENT_INVENTORY FROM snitch_db.maplemonk.category_overall_data WHERE SKU_GROUP IS NOT NULL ), capsule_master_base AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, UPPER(TRIM(CAPSULE)) AS CAPSULE, COALESCE(TOTAL_QTY, 0) AS TOTAL_QTY, COALESCE(TOTAL_INWARD_QTY, 0) AS TOTAL_INWARD_QTY FROM snitch_db.maplemonk.capsule_master_summary_tbl WHERE SKU_GROUP IS NOT NULL AND CAPSULE IS NOT NULL ), rolling_30_metrics AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, UPPER(TRIM(CAPSULE)) AS CAPSULE, MIN(LAUNCH_DATE) AS LAUNCH_DATE, ROUND( AVG(NORMALIZED_30_STR), 2 ) AS NORMALIZED_30_STR, ROUND( AVG(STR), 2 ) AS ACTUAL_STR FROM snitch_db.maplemonk.rolling_30_days_dashboard WHERE SKU_GROUP IS NOT NULL AND CAPSULE IS NOT NULL GROUP BY UPPER(TRIM(SKU_GROUP)), UPPER(TRIM(CAPSULE)) ), capsule_master_metrics AS ( SELECT fc.CAPSULE, SUM(cmb.TOTAL_QTY) AS CAPSULE_TOTAL_QTY, SUM(cmb.TOTAL_INWARD_QTY) AS CAPSULE_MASTER_INWARD_QTY, ROUND( ( SUM(cmb.TOTAL_QTY) / NULLIF( SUM(cmb.TOTAL_INWARD_QTY), 0 ) ) * 100, 2 ) AS CAPSULE_LIFETIME_STR FROM focus_capsules fc LEFT JOIN capsule_master_base cmb ON fc.SKU_GROUP = cmb.SKU_GROUP AND LOWER(TRIM(fc.CAPSULE)) = LOWER(TRIM(cmb.CAPSULE)) GROUP BY fc.CAPSULE ), capsule_rolling_metrics AS ( SELECT fc.CAPSULE, MIN(r30.LAUNCH_DATE) AS LAUNCH_DATE, DATEDIFF( DAY, MIN(r30.LAUNCH_DATE), CURRENT_DATE() ) AS DAYS_SINCE_LAUNCH, ROUND( AVG(r30.NORMALIZED_30_STR), 2 ) AS NORMALIZED_CAPSULE_STR, ROUND( AVG(r30.ACTUAL_STR), 2 ) AS ACTUAL_CAPSULE_STR FROM focus_capsules fc LEFT JOIN rolling_30_metrics r30 ON fc.SKU_GROUP = r30.SKU_GROUP AND LOWER(TRIM(fc.CAPSULE)) = LOWER(TRIM(r30.CAPSULE)) GROUP BY fc.CAPSULE ), capsule_metrics AS ( SELECT fc.CAPSULE, cb.L1_CATEGORY, cb.CATEGORY, SUM(cb.L30D_QTY) AS CAPSULE_L30D_QTY, SUM(cb.INWARD_QTY) AS CAPSULE_INWARD_QTY, SUM(cb.CURRENT_INVENTORY) AS CAPSULE_CURRENT_INVENTORY FROM focus_capsules fc INNER JOIN category_base cb ON fc.SKU_GROUP = cb.SKU_GROUP GROUP BY fc.CAPSULE, cb.L1_CATEGORY, cb.CATEGORY ), capsule_final_metrics AS ( SELECT cm.CAPSULE, cm.L1_CATEGORY, cm.CATEGORY, cm.CAPSULE_L30D_QTY, cm.CAPSULE_INWARD_QTY, cm.CAPSULE_CURRENT_INVENTORY, cmm.CAPSULE_TOTAL_QTY, cmm.CAPSULE_MASTER_INWARD_QTY, cmm.CAPSULE_LIFETIME_STR, crm.LAUNCH_DATE, crm.DAYS_SINCE_LAUNCH, ROUND( crm.NORMALIZED_CAPSULE_STR, 2 ) AS NORMALIZED_CAPSULE_STR, ROUND( crm.ACTUAL_CAPSULE_STR, 2 ) AS ACTUAL_CAPSULE_STR, ROUND( CASE WHEN crm.LAUNCH_DATE IS NULL THEN crm.ACTUAL_CAPSULE_STR WHEN crm.DAYS_SINCE_LAUNCH < 30 THEN crm.NORMALIZED_CAPSULE_STR ELSE crm.ACTUAL_CAPSULE_STR END, 2 ) AS CAPSULE_STR, CASE WHEN crm.LAUNCH_DATE IS NULL THEN \'ACTUAL STR\' WHEN crm.DAYS_SINCE_LAUNCH < 30 THEN \'NORMALIZED 30D STR\' ELSE \'ACTUAL STR\' END AS STR_TYPE_USED FROM capsule_metrics cm LEFT JOIN capsule_master_metrics cmm ON LOWER(TRIM(cm.CAPSULE)) = LOWER(TRIM(cmm.CAPSULE)) LEFT JOIN capsule_rolling_metrics crm ON LOWER(TRIM(cm.CAPSULE)) = LOWER(TRIM(crm.CAPSULE)) ), category_metrics AS ( SELECT L1_CATEGORY, CATEGORY, SUM(L30D_QTY) AS CATEGORY_L30D_QTY, SUM(INWARD_QTY) AS CATEGORY_INWARD_QTY, SUM(CURRENT_INVENTORY) AS CATEGORY_CURRENT_INVENTORY, ROUND( ( SUM(L30D_QTY) / NULLIF( SUM(INWARD_QTY), 0 ) ) * 100, 2 ) AS CATEGORY_STR FROM category_base GROUP BY L1_CATEGORY, CATEGORY ) SELECT cfm.CAPSULE, cfm.L1_CATEGORY, cfm.CATEGORY, cfm.LAUNCH_DATE, cfm.DAYS_SINCE_LAUNCH, cfm.CAPSULE_L30D_QTY, cfm.CAPSULE_INWARD_QTY, cfm.CAPSULE_CURRENT_INVENTORY, cfm.CAPSULE_TOTAL_QTY, cfm.CAPSULE_MASTER_INWARD_QTY, ROUND( cfm.CAPSULE_LIFETIME_STR, 2 ) AS CAPSULE_LIFETIME_STR, ROUND( cfm.NORMALIZED_CAPSULE_STR, 2 ) AS NORMALIZED_CAPSULE_STR, ROUND( cfm.ACTUAL_CAPSULE_STR, 2 ) AS ACTUAL_CAPSULE_STR, ROUND( cfm.CAPSULE_STR, 2 ) AS CAPSULE_STR, cfm.STR_TYPE_USED, cat.CATEGORY_L30D_QTY, cat.CATEGORY_INWARD_QTY, cat.CATEGORY_CURRENT_INVENTORY, ROUND( cat.CATEGORY_STR, 2 ) AS CATEGORY_STR, ROUND( cfm.CAPSULE_STR / NULLIF( cat.CATEGORY_STR, 0 ), 2 ) AS STR_INDEX, CASE WHEN cfm.CAPSULE_STR IS NULL THEN \'NO CAPSULE DATA\' WHEN cat.CATEGORY_STR IS NULL THEN \'NO CATEGORY DATA\' WHEN cfm.CAPSULE_STR > cat.CATEGORY_STR THEN \'OUTPERFORMING\' WHEN cfm.CAPSULE_STR < cat.CATEGORY_STR THEN \'UNDERPERFORMING\' ELSE \'AT PAR\' END AS STR_PERFORMANCE FROM capsule_final_metrics cfm LEFT JOIN category_metrics cat ON LOWER(TRIM(cfm.L1_CATEGORY)) = LOWER(TRIM(cat.L1_CATEGORY)) AND LOWER(TRIM(cfm.CATEGORY)) = LOWER(TRIM(cat.CATEGORY)) ORDER BY cfm.CAPSULE, cfm.CAPSULE_STR DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            